package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.FormElement;
import org.jsoup.nodes.Tag;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class FormElement_formData_TriageGen1Test {

    @Test
    public void formData_EmptyForm_ReturnsEmptyList() {
        // Arrange
        FormElement form = new FormElement(Tag.valueOf("form"), "", new Attributes());

        // Act
        List<Connection.KeyVal> result = form.formData();

        // Assert
        assertTrue(result.isEmpty());
    }

    @Test
    public void formData_SingleInputNoName_ReturnsEmptyList() {
        // Arrange
        FormElement form = new FormElement(Tag.valueOf("form"), "", new Attributes());
        Element input = new Element(Tag.valueOf("input"), "");
        form.addElement(input);

        // Act
        List<Connection.KeyVal> result = form.formData();

        // Assert
        assertTrue(result.isEmpty());
    }

    @Test
    public void formData_SingleInputWithName_ReturnsSingleKV() {
        // Arrange
        FormElement form = new FormElement(Tag.valueOf("form"), "", new Attributes());
        Element input = new Element(Tag.valueOf("input"), "");
        input.attr("name", "test");
        form.addElement(input);

        // Act
        List<Connection.KeyVal> result = form.formData();

        // Assert
        assertEquals(1, result.size());
        assertEquals("test", result.get(0).key());
        assertEquals("", result.get(0).value());
    }

    @Test
    public void formData_SingleInputWithType_ReturnsSingleKV() {
        // Arrange
        FormElement form = new FormElement(Tag.valueOf("form"), "", new Attributes());
        Element input = new Element(Tag.valueOf("input"), "");
        input.attr("name", "test");
        input.attr("type", "text");
        form.addElement(input);

        // Act
        List<Connection.KeyVal> result = form.formData();

        // Assert
        assertEquals(1, result.size());
        assertEquals("test", result.get(0).key());
        assertEquals("", result.get(0).value());
    }

    @Test
    public void formData_SingleSelect_ReturnsSingleKV() {
        // Arrange
        FormElement form = new FormElement(Tag.valueOf("form"), "", new Attributes());
        Element select = new Element(Tag.valueOf("select"), "");
        select.attr("name", "test");
        Element option = new Element(Tag.valueOf("option"), "");
        option.attr("selected", "true");
        option.attr("value", "value");
        select.appendChild(option);
        form.addElement(select);

        // Act
        List<Connection.KeyVal> result = form.formData();

        // Assert
        assertEquals(1, result.size());
        assertEquals("test", result.get(0).key());
        assertEquals("value", result.get(0).value());
    }

    @Test
    public void formData_SingleCheckbox_ReturnsEmptyList() {
        // Arrange
        FormElement form = new FormElement(Tag.valueOf("form"), "", new Attributes());
        Element checkbox = new Element(Tag.valueOf("input"), "");
        checkbox.attr("name", "test");
        checkbox.attr("type", "checkbox");
        form.addElement(checkbox);

        // Act
        List<Connection.KeyVal> result = form.formData();

        // Assert
        assertTrue(result.isEmpty());
    }

    @Test
    public void formData_SingleRadio_ReturnsSingleKV() {
        // Arrange
        FormElement form = new FormElement(Tag.valueOf("form"), "", new Attributes());
        Element radio = new Element(Tag.valueOf("input"), "");
        radio.attr("name", "test");
        radio.attr("type", "radio");
        radio.attr("checked", "true");
        form.addElement(radio);

        // Act
        List<Connection.KeyVal> result = form.formData();

        // Assert
        assertEquals(1, result.size());
        assertEquals("test", result.get(0).key());
        assertEquals("", result.get(0).value());
    }

    @Test
    public void formData_SingleInputWithValue_ReturnsSingleKV() {
        // Arrange
        FormElement form = new FormElement(Tag.valueOf("form"), "", new Attributes());
        Element input = new Element(Tag.valueOf("input"), "");
        input.attr("name", "test");
        input.val("value");
        form.addElement(input);

        // Act
        List<Connection.KeyVal> result = form.formData();

        // Assert
        assertEquals(1, result.size());
        assertEquals("test", result.get(0).key());
        assertEquals("value", result.get(0).value());
    }

    @Test
    public void formData_SingleHiddenInput_ReturnsSingleKV() {
        // Arrange
        FormElement form = new FormElement(Tag.valueOf("form"), "", new Attributes());
        Element input = new Element(Tag.valueOf("input"), "");
        input.attr("name", "test");
        input.attr("type", "hidden");
        input.val("value");
        form.addElement(input);

        // Act
        List<Connection.KeyVal> result = form.formData();

        // Assert
        assertEquals(1, result.size());
        assertEquals("test", result.get(0).key());
        assertEquals("value", result.get(0).value());
    }
}
